# qx_quadratic :: (1, -5, 6)
def qx_quadratic(a, b, c):
    import math
    d = b*b - 4*a*c
    if d < 0: return ()
    sd = math.sqrt(d)
    return ((-b + sd) / (2*a), (-b - sd) / (2*a))

if __name__ == '__main__':
    print(qx_quadratic((1, -5, 6)))

